draw:
var r = p.radius, v = p.speed, m = p.mass;
var a = v * v / r;
var T = 2 * Math.PI * r / v;
var om = v / r;
var F = m * a;

var cx = W * 0.42, cy = H * 0.52;
var R = Math.min(W * 0.26, H * 0.34);
var ang = (v / r) * t;

ctx.lineWidth = 1;
ctx.strokeStyle = C.rule;
ctx.setLineDash([4, 5]);
ctx.beginPath(); ctx.arc(cx, cy, R, 0, Math.PI * 2); ctx.stroke();
ctx.setLineDash([]);

var bx = cx + R * Math.cos(ang), by = cy + R * Math.sin(ang);

// radius line
ctx.strokeStyle = C.faint;
ctx.beginPath(); ctx.moveTo(cx, cy); ctx.lineTo(bx, by); ctx.stroke();

ctx.font = "12px ui-sans-serif, system-ui, sans-serif";

function arrow(x0, y0, x1, y1, col) {
  ctx.strokeStyle = col; ctx.fillStyle = col; ctx.lineWidth = 2;
  ctx.beginPath(); ctx.moveTo(x0, y0); ctx.lineTo(x1, y1); ctx.stroke();
  var th = Math.atan2(y1 - y0, x1 - x0);
  ctx.beginPath();
  ctx.moveTo(x1, y1);
  ctx.lineTo(x1 - 8 * Math.cos(th - 0.4), y1 - 8 * Math.sin(th - 0.4));
  ctx.lineTo(x1 - 8 * Math.cos(th + 0.4), y1 - 8 * Math.sin(th + 0.4));
  ctx.closePath(); ctx.fill();
  ctx.lineWidth = 1;
}

// velocity: tangent, length fixed-ish scaled by speed
var vlen = R * 0.35 * (v / 12) + R * 0.25;
var tx = -Math.sin(ang), ty = Math.cos(ang);
arrow(bx, by, bx + tx * vlen, by + ty * vlen, C.figure);
ctx.fillStyle = C.figure;
ctx.fillText("v", bx + tx * vlen + 6, by + ty * vlen + 4);

// acceleration: inward
var alen = R * 0.55 * Math.min(1, a / 120) + R * 0.18;
arrow(bx, by, bx - Math.cos(ang) * alen, by - Math.sin(ang) * alen, C.accent);
ctx.fillStyle = C.accent;
ctx.fillText("a = v^2/r", bx - Math.cos(ang) * alen - 30, by - Math.sin(ang) * alen - 8);

// ball and centre
ctx.fillStyle = C.accent;
ctx.beginPath(); ctx.arc(bx, by, 6, 0, Math.PI * 2); ctx.fill();
ctx.fillStyle = C.ink;
ctx.beginPath(); ctx.arc(cx, cy, 3, 0, Math.PI * 2); ctx.fill();
ctx.fillText("r = " + r.toFixed(1) + " m", cx + 6, cy - 8);

// speed trace: the speed never changes, show a bar
var px = W * 0.78;
ctx.strokeStyle = C.rule;
ctx.beginPath(); ctx.moveTo(px, H * 0.18); ctx.lineTo(px, H * 0.82); ctx.stroke();
ctx.fillStyle = C.faint;
ctx.fillRect(px + 4, H * 0.82 - (H * 0.64) * (v / 12), 16, (H * 0.64) * (v / 12));
ctx.fillStyle = C.ink;
ctx.fillText("speed", px - 4, H * 0.14);
ctx.fillText(v.toFixed(1) + " m/s", px - 4, H * 0.9);

out.note = "a = " + a.toFixed(2) + " m/s^2,  F = m a = " + F.toFixed(2) + " N,  period T = " + T.toFixed(2) + " s,  omega = " + om.toFixed(2) + " rad/s";
